'use client';

import { useEffect, useState } from 'react';

export default function Posts() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  // Runs in the browser: double round-trip, no caching at the
  // framework layer, and the fetch logic ships to every client.
  useEffect(() => {
    let cancelled = false;
    fetch('/api/posts')
      .then((r) => r.json())
      .then((data) => {
        if (!cancelled) {
          setPosts(data);
          setLoading(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (loading) return <p>Loading posts…</p>;
  return (
    <ul>
      {posts.map((p) => (
        <li key={p.id}>{p.title}</li>
      ))}
    </ul>
  );
}

