import { db } from '@/lib/db';

export default async function Posts() {
  // Runs once, on the server, during SSR/prerender. The query
  // result is serialized into the RSC payload; the fetch logic
  // and DB driver never reach the client bundle.
  const posts = await db.query('SELECT id, title FROM posts');

  return (
    <ul>
      {posts.map((p) => (
        <li key={p.id}>{p.title}</li>
      ))}
    </ul>
  );
}

// A tiny client island is only needed when the list must be
// interactive; the rest of the tree stays server-rendered.
